		t.Fatal(err)
	}
	if httpResp != nil && httpResp.Body != nil {
		httpResp.Body.Close()
	}
	if len(entries) != 1 {
		t.Fatalf("entries: %#v", entries)
	}
	mapped, err = daytonaFileInfo(&entries[0], "list_directory")
	if err != nil {
		t.Fatal(err)
	}
	if mapped.GetPath() != "/tmp/note.txt" || mapped.GetOwner() != "daytona" {
		t.Fatalf("list: %#v", mapped)
	}
}

